window.ZK_PRED["15044"]={"meta": "分析范围：2008—2026 年共 41 套真题（选择 1370 题）。注意：平台马原真题仅 2026 年 4 月一套含简答/论述（5 简 + 3 论），故主观题方向以 2026 真题 + 教材核心为准；展开的模拟题参考真题出题风格拟写。", "heat": [{"name": "商品经济与资本主义形成", "n": 204, "n5": 22}, {"name": "历史唯物论", "n": 198, "n5": 26}, {"name": "马克思主义总论", "n": 163, "n5": 26}, {"name": "认识论", "n": 156, "n5": 28}, {"name": "唯物辩证法", "n": 130, "n5": 24}, {"name": "垄断资本主义", "n": 101, "n5": 21}, {"name": "社会主义", "n": 97, "n5": 12}, {"name": "共产主义", "n": 31, "n5": 4}], "groups": [{"title": "客观题 · 八大章核心考点（41 套全考分布）", "items": [{"tier": 3, "topic": "商品经济：价值规律 / 商品二因素 / 货币职能", "stat": "204 题 · 18 年连续出题", "reason": "选择题第一大板块，政治经济学基础概念几乎每年 4-6 题。", "q": [{"t": "单选", "q": "商品的二因素是", "o": ["A.使用价值和价值", "B.具体劳动和抽象劳动", "C.私人劳动和社会劳动", "D.价值和交换价值"], "a": "A"}, {"t": "单选", "q": "决定商品价值量的是", "o": ["A.个别劳动时间", "B.社会必要劳动时间", "C.商品供求关系", "D.劳动生产率"], "a": "B"}, {"t": "单选", "q": "价值规律的表现形式是", "o": ["A.价格围绕价值上下波动", "B.价值围绕价格上下波动", "C.价格与价值永远一致", "D.供求决定价格"], "a": "A"}]}, {"tier": 3, "topic": "历史唯物论：社会存在与社会意识 / 生产力", "stat": "198 题 · 近 5 年 26 题", "reason": "唯物史观核心原理，社会存在决定社会意识是最高频单选。", "q": [{"t": "单选", "q": "社会存在是指", "o": ["A.社会物质生活条件的总和", "B.社会精神生活", "C.生产方式", "D.经济基础"], "a": "A"}, {"t": "单选", "q": "社会意识相对独立性的最突出表现是", "o": ["A.对社会存在具有能动的反作用", "B.与社会存在发展的不平衡性", "C.历史继承性", "D.社会意识形式的相互影响"], "a": "A"}, {"t": "单选", "q": "推动社会历史发展的最终决定力量是", "o": ["A.生产力", "B.生产关系", "C.人民群众", "D.科学技术"], "a": "A"}]}, {"tier": 3, "topic": "马克思主义总论：物质观 / 哲学基本问题", "stat": "163 题 · 近 5 年 26 题", "reason": "第一章基础概念，物质唯一特性“客观实在性”是经典考点。", "q": [{"t": "单选", "q": "物质的唯一特性是", "o": ["A.客观实在性", "B.运动性", "C.可知性", "D.广延性"], "a": "A"}, {"t": "单选", "q": "哲学的基本问题是", "o": ["A.思维和存在的关系问题", "B.运动和静止的关系问题", "C.理论和实践的关系问题", "D.物质和意识的关系问题"], "a": "A"}, {"t": "单选", "q": "划分唯物主义与唯心主义的唯一标准是", "o": ["A.对思维和存在何者为第一性问题的不同回答", "B.是否承认运动", "C.是否承认矛盾", "D.是否承认实践"], "a": "A"}]}, {"tier": 3, "topic": "认识论：实践与认识 / 真理观", "stat": "156 题 · 近 5 年 28 题（最活跃）", "reason": "近五年选择题最活跃板块，真理观与认识过程连考。", "q": [{"t": "单选", "q": "认识的本质是", "o": ["A.主体对客体的能动反映", "B.主观自生的", "C.直观的照镜子式反映", "D.天赋观念"], "a": "A"}, {"t": "单选", "q": "检验真理的唯一标准是", "o": ["A.实践", "B.理论", "C.逻辑证明", "D.权威意见"], "a": "A"}, {"t": "单选", "q": "认识过程的第一次飞跃是指", "o": ["A.从感性认识上升到理性认识", "B.从理性认识回到实践", "C.从实践到认识的飞跃", "D.从认识到真理的飞跃"], "a": "A"}]}, {"tier": 3, "topic": "唯物辩证法：三大规律 / 矛盾观", "stat": "130 题 · 近 5 年 24 题", "reason": "三大规律+五对范畴是选择题常青树，矛盾观出题最多。", "q": [{"t": "单选", "q": "唯物辩证法的实质和核心是", "o": ["A.对立统一规律", "B.质量互变规律", "C.否定之否定规律", "D.普遍联系的观点"], "a": "A"}, {"t": "单选", "q": "“共性寓于个性之中”体现的矛盾原理是", "o": ["A.矛盾的普遍性与特殊性关系", "B.主要矛盾与次要矛盾关系", "C.矛盾主要方面与次要方面关系", "D.内因与外因关系"], "a": "A"}, {"t": "单选", "q": "量变与质变的辩证统一表明，事物的发展是", "o": ["A.渐进性与飞跃性的统一", "B.前进性与曲折性的统一", "C.绝对性与相对性的统一", "D.连续性与间断性的对立"], "a": "A"}]}, {"tier": 3, "topic": "垄断资本主义：垄断特征 / 金融资本 / 经济全球化", "stat": "101 题 · 近 5 年 21 题", "reason": "资本主义发展新阶段考点，垄断形成与金融资本是核心。", "q": [{"t": "单选", "q": "垄断资本主义阶段的主要标志是", "o": ["A.垄断在经济生活中占统治地位", "B.资本输出", "C.金融资本统治", "D.国家垄断"], "a": "A"}, {"t": "单选", "q": "垄断利润的最终来源是", "o": ["A.工人创造的剩余价值", "B.垄断价格", "C.竞争", "D.平均利润"], "a": "A"}, {"t": "单选", "q": "金融资本是", "o": ["A.银行垄断资本与工业垄断资本融合形成的资本", "B.借贷资本", "C.商业资本", "D.产业资本"], "a": "A"}]}, {"tier": 2, "topic": "社会主义：社会主义本质 / 中国特色社会主义", "stat": "97 题 · 近 5 年 12 题", "reason": "社会主义理论稳定出题，注意与“苏联模式”评价连考。", "q": [{"t": "单选", "q": "邓小平概括的社会主义本质是", "o": ["A.解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕", "B.公有制和按劳分配", "C.计划经济", "D.人民民主专政"], "a": "A"}, {"t": "单选", "q": "中国特色社会主义最本质的特征是", "o": ["A.中国共产党领导", "B.人民民主专政", "C.公有制为主体", "D.人民代表大会制度"], "a": "A"}, {"t": "单选", "q": "社会主义社会的基本矛盾仍然是", "o": ["A.生产力和生产关系、经济基础和上层建筑之间的矛盾", "B.阶级矛盾", "C.人民内部矛盾", "D.敌我矛盾"], "a": "A"}]}, {"tier": 2, "topic": "共产主义：基本特征 / 自由王国", "stat": "31 题 · 近 5 年 4 题（频率低）", "reason": "第七章低频但稳定，每年 0-1 题，重点记“按需分配”“人的自由全面发展”。", "q": [{"t": "单选", "q": "共产主义社会的分配方式是", "o": ["A.按需分配", "B.按劳分配", "C.按资分配", "D.平均分配"], "a": "A"}, {"t": "单选", "q": "共产主义社会的根本特征是", "o": ["A.人的自由而全面的发展", "B.消灭国家", "C.物质极大丰富", "D.社会大同"], "a": "A"}, {"t": "单选", "q": "“必然王国”是指人们受", "o": ["A.盲目必然性支配的状态", "B.自由支配的状态", "C.法律约束的状态", "D.道德约束的状态"], "a": "A"}]}]}, {"title": "客观题 · 近 5 年高频细分考点", "items": [{"tier": 3, "topic": "剩余价值理论：绝对/相对/超额剩余价值", "stat": "资本主义章内最高频子题", "reason": "剥削程度与生产方法对比是经典题，2026.4 论述亦考价值量。", "q": [{"t": "单选", "q": "资本家提高剥削程度的两种基本方法是", "o": ["A.绝对剩余价值生产和相对剩余价值生产", "B.延长工作日和增加劳动强度", "C.提高劳动生产率和降低成本", "D.计件工资和计时工资"], "a": "A"}, {"t": "单选", "q": "超额剩余价值是", "o": ["A.个别资本家提高劳动生产率获得的", "B.全体资本家都能获得的", "C.流通领域中产生的", "D.垄断产生的"], "a": "A"}, {"t": "单选", "q": "剩余价值率反映", "o": ["A.资本家对工人的剥削程度", "B.资本的周转速度", "C.资本的积累规模", "D.利润率的水平"], "a": "A"}]}, {"tier": 3, "topic": "货币的职能", "stat": "高频", "reason": "五种职能区分题每年 1-2 道。", "q": [{"t": "单选", "q": "货币最基本的职能是", "o": ["A.价值尺度和流通手段", "B.支付手段和贮藏手段", "C.世界货币和支付手段", "D.流通手段和贮藏手段"], "a": "A"}, {"t": "单选", "q": "“一手交钱、一手交货”体现货币的职能是", "o": ["A.流通手段", "B.价值尺度", "C.支付手段", "D.贮藏手段"], "a": "A"}, {"t": "单选", "q": "用货币衡量商品价值大小，体现货币的职能是", "o": ["A.价值尺度", "B.流通手段", "C.支付手段", "D.世界货币"], "a": "A"}]}, {"tier": 3, "topic": "矛盾的普遍性与特殊性（共性与个性）", "stat": "高频", "reason": "“共性寓于个性”是辩证法最高频原句选择题。", "q": [{"t": "单选", "q": "矛盾的普遍性是指", "o": ["A.矛盾存在于一切事物中并贯穿发展全过程", "B.不同事物矛盾各不相同", "C.矛盾可以人为消除", "D.矛盾双方绝对对立"], "a": "A"}, {"t": "单选", "q": "“白马非马”的错误在于", "o": ["A.割裂了共性与个性的关系", "B.否定了矛盾的普遍性", "C.混淆了主要矛盾", "D.颠倒了内因外因"], "a": "A"}, {"t": "单选", "q": "具体问题具体分析是马克思主义的", "o": ["A.活的灵魂", "B.理论基础", "C.根本方法", "D.基本立场"], "a": "A"}]}, {"tier": 3, "topic": "人民群众是历史的创造者", "stat": "高频", "reason": "唯物史观立场题，与英雄史观对比。", "q": [{"t": "单选", "q": "人民群众创造历史的作用最突出地表现在", "o": ["A.物质财富的创造上", "B.精神财富的创造上", "C.社会变革的决定力量上", "D.历史发展的唯一动力上"], "a": "C"}, {"t": "单选", "q": "群众史观与英雄史观的根本区别在于", "o": ["A.是否承认人民群众是历史的创造者", "B.是否承认个人的作用", "C.是否承认阶级斗争", "D.是否承认生产力"], "a": "A"}, {"t": "单选", "q": "党的群众路线的基本内容是", "o": ["A.一切为了群众，一切依靠群众，从群众中来，到群众中去", "B.实事求是", "C.独立自主", "D.自力更生"], "a": "A"}]}, {"tier": 2, "topic": "认识过程的两次飞跃", "stat": "高频", "reason": "认识论过程题常设。", "q": [{"t": "单选", "q": "认识过程的第二次飞跃是", "o": ["A.从理性认识到实践", "B.从感性认识到理性认识", "C.从实践到感性认识", "D.从认识到真理"], "a": "A"}, {"t": "单选", "q": "实现感性认识到理性认识飞跃的条件是", "o": ["A.占有丰富可靠的感性材料并进行加工制作", "B.只要有感性材料即可", "C.依靠逻辑证明", "D.依靠权威认可"], "a": "A"}, {"t": "单选", "q": "感性认识与理性认识统一的基础是", "o": ["A.实践", "B.感觉", "C.思维", "D.直观"], "a": "A"}]}, {"tier": 2, "topic": "资本主义经济危机", "stat": "高频", "reason": "危机根源=生产社会化与生产资料私有制矛盾。", "q": [{"t": "单选", "q": "资本主义经济危机的实质是", "o": ["A.生产相对过剩的危机", "B.生产绝对过剩", "C.商品供不应求", "D.货币供应不足"], "a": "A"}, {"t": "单选", "q": "资本主义经济危机的根源在于", "o": ["A.资本主义基本矛盾", "B.生产的无政府状态", "C.劳动者消费不足", "D.分配不公"], "a": "A"}, {"t": "单选", "q": "经济危机周期性爆发的物质基础是", "o": ["A.固定资本更新", "B.机器大工业", "C.市场扩大", "D.技术进步"], "a": "A"}]}, {"tier": 2, "topic": "国家垄断资本主义", "stat": "高频", "reason": "垄断阶段政策手段题。", "q": [{"t": "单选", "q": "国家垄断资本主义产生发展的根本原因是", "o": ["A.生产社会化与私人垄断资本之间的矛盾", "B.战争的需要", "C.政府干预偏好", "D.经济危机"], "a": "A"}, {"t": "单选", "q": "下列不属于国家垄断资本主义主要形式的是", "o": ["A.国有企业", "B.国家与私人共有的垄断资本", "C.国家调节和干预经济", "D.自由竞争"], "a": "D"}, {"t": "单选", "q": "国家垄断资本主义的本质是", "o": ["A.为垄断资产阶级的整体利益服务", "B.为全社会人民服务", "C.社会主义的萌芽", "D.消除竞争"], "a": "A"}]}, {"tier": 2, "topic": "价值规律的作用", "stat": "高频", "reason": "商品经济基本规律题。", "q": [{"t": "单选", "q": "价值规律调节社会资源配置是通过", "o": ["A.价格围绕价值上下波动实现的", "B.政府计划实现的", "C.垄断定价实现的", "D.市场自发实现的"], "a": "A"}, {"t": "单选", "q": "价值规律的作用不包括", "o": ["A.自发地刺激社会生产力的发展", "B.调节生产资料和劳动力在社会各部门的分配", "C.促使商品生产者优胜劣汰", "D.消除两极分化"], "a": "D"}, {"t": "单选", "q": "商品经济的基本矛盾是", "o": ["A.私人劳动和社会劳动的矛盾", "B.使用价值和价值的矛盾", "C.具体劳动和抽象劳动的矛盾", "D.生产和消费的矛盾"], "a": "A"}]}]}, {"title": "主观题方向（2026.4 真题 + 教材核心大题）", "items": [{"tier": 3, "topic": "社会存在与社会意识", "stat": "2026.4 简答原题", "reason": "唯物史观总论大题，教材标准大题，随时可能再考变形（如“社会意识相对独立性”）。", "q": [{"t": "简答", "q": "简述社会存在和社会意识的含义及辩证关系", "a": "社会存在是社会物质生活条件的总和，社会意识是社会精神生活过程的总和。社会存在决定社会意识，社会意识具有相对独立性并能动地反作用于社会存在。"}, {"t": "论述", "q": "试述社会意识相对独立性的表现及其意义", "a": "表现：社会意识与社会存在发展的不平衡性；历史继承性；相互影响；对社会存在具有能动的反作用，这是最突出的表现。意义：重视先进意识的作用，加强精神文明建设。"}]}, {"tier": 3, "topic": "价值观 + 社会主义核心价值观", "stat": "2026.4 简答原题", "reason": "马原与新时代结合题，价值观导向大题。", "q": [{"t": "简答", "q": "简述价值观的含义及其作用", "a": "价值观是人们对价值的根本看法和观点，具有导向、约束、凝聚和激励作用，对人们认识世界和改造世界具有重要指导意义。"}, {"t": "简答", "q": "简述社会主义核心价值观的基本内容", "a": "富强、民主、文明、和谐（国家层面）；自由、平等、公正、法治（社会层面）；爱国、敬业、诚信、友善（个人层面）。"}]}, {"tier": 3, "topic": "两点论与重点论统一原理", "stat": "2026.4 论述原题", "reason": "辩证法方法论大题，主次矛盾原理的应用。", "q": [{"t": "简答", "q": "简述两点论和重点论相统一的原理", "a": "主次矛盾和矛盾主次方面相互关系的原理要求我们：看问题既要全面（两点论），又要抓重点（重点论），两点是有重点的两点，重点是两点中的重点。"}, {"t": "论述", "q": "试述两点论和重点论统一原理的现实意义", "a": "在认识和处理问题时，既要全面分析矛盾，又要抓住主要矛盾和矛盾的主要方面，反对形而上学的一点论和均衡论；在实际工作中要抓中心、抓关键，同时兼顾一般。"}]}, {"tier": 3, "topic": "商品价值量的决定", "stat": "2026.4 论述原题", "reason": "政治经济学核心大题，社会必要劳动时间+劳动生产率反向关系。", "q": [{"t": "简答", "q": "简述商品价值量的决定因素", "a": "商品价值量由生产商品的社会必要劳动时间决定，与劳动生产率成反比，与体现在商品中的劳动量成正比。"}, {"t": "论述", "q": "试述劳动生产率与商品价值量的关系", "a": "劳动生产率越高，同一时间内生产的使用价值越多，单位商品包含的社会必要劳动时间越少，价值量越小；反之越大。商品价值量与社会劳动生产率成反比，与个别劳动生产率无关（但可获超额剩余价值）。"}]}, {"tier": 3, "topic": "真理的绝对性与相对性", "stat": "教材核心大题", "reason": "认识论最经典大题，未在 2026.4 出现，概率高。", "q": [{"t": "简答", "q": "简述真理的绝对性和相对性的含义", "a": "真理的绝对性指真理的内容是对客观事物及其规律的正确反映，承认真理客观性和可知性；真理的相对性指真理是对客观世界的有限度、有条件、不完全的正确反映。"}, {"t": "论述", "q": "试述真理的绝对性和相对性的辩证关系及现实意义", "a": "二者相互依存、相互包含、相互转化，任何真理都是绝对与相对的统一。意义：既要坚持真理又要发展真理，反对绝对主义和相对主义，在实践中不断丰富发展真理。"}]}, {"tier": 3, "topic": "意识的能动作用", "stat": "教材核心大题", "reason": "唯物论大题常客。", "q": [{"t": "简答", "q": "简述意识能动作用的表现", "a": "意识具有目的性和计划性；具有主动创造性；对人的生理活动具有调控作用；通过实践改造客观世界，这是最突出的表现。"}, {"t": "论述", "q": "试述物质和意识的辩证关系及方法论意义", "a": "物质决定意识，意识对物质具有能动的反作用。方法论：一切从实际出发，实事求是；重视和发挥意识的能动作用，正确发挥主观能动性。"}]}, {"tier": 3, "topic": "对立统一规律是唯物辩证法的实质与核心", "stat": "教材核心大题", "reason": "辩证法总纲大题。", "q": [{"t": "简答", "q": "为什么说对立统一规律是唯物辩证法的实质和核心", "a": "它揭示了事物普遍联系的根本内容和变化发展的内在动力；是贯穿其他规律和范畴的中心线索；矛盾分析法是最根本的认识方法；是否承认矛盾是辩证法和形而上学对立的焦点。"}, {"t": "论述", "q": "试述矛盾分析法的主要内容及其意义", "a": "矛盾分析法包括分析矛盾的普遍性与特殊性、主要矛盾与次要矛盾、矛盾主要方面与次要方面等方法，坚持两点论与重点论统一、具体问题具体分析。意义：是认识世界和改造世界的根本方法。"}]}, {"tier": 3, "topic": "生产力与生产关系的矛盾运动规律", "stat": "教材核心大题", "reason": "历史唯物论核心大题，与“改革是社会主义发展动力”连考。", "q": [{"t": "简答", "q": "简述生产力和生产关系的辩证关系", "a": "生产力决定生产关系，生产关系对生产力具有能动的反作用：适合时促进，不适合时阻碍。"}, {"t": "论述", "q": "试述生产力与生产关系矛盾运动规律的现实意义", "a": "这一规律是马克思主义政党制定路线方针政策的重要依据；改革是社会主义制度的自我完善和发展，通过改革调整生产关系不适应生产力的环节，解放和发展生产力。"}]}, {"tier": 2, "topic": "资本主义基本矛盾与历史趋势", "stat": "教材核心大题", "reason": "垄断章总结性大题。", "q": [{"t": "简答", "q": "简述资本主义基本矛盾的表现", "a": "生产社会化与生产资料资本主义私人占有之间的矛盾，表现为个别企业生产的有组织性与整个社会生产的无政府状态之间的矛盾，生产无限扩大趋势与劳动人民支付能力相对缩小之间的矛盾。"}, {"t": "论述", "q": "试述资本主义必然被社会主义所代替的历史趋势", "a": "资本主义基本矛盾的发展决定了资本主义制度的暂时性和历史过渡性；生产社会化程度的提高为社会主义准备了物质条件；无产阶级力量的壮大是资本主义的掘墓人；社会主义代替资本主义是历史发展的必然趋势。"}]}, {"tier": 2, "topic": "社会主义代替资本主义的历史必然性", "stat": "教材核心大题", "reason": "六章收尾大题，常与“两个必然”连考。", "q": [{"t": "简答", "q": "简述“两个必然”的含义", "a": "资本主义必然灭亡，社会主义必然胜利。这是马克思、恩格斯依据历史唯物主义揭示的社会历史发展的必然趋势。"}, {"t": "论述", "q": "试述社会主义代替资本主义的长期性和艰巨性", "a": "资产阶级会采取各种手段维护其统治；社会主义国家在较长时期内处于劣势；两种制度并存和斗争是长期的。因此既要坚定信念，又要充分认识过程的长期性。"}]}]}]};
