Object.assign(window.ZK_MM15044,{"1":[{"root":"绪论","sects":[{"s":"马克思主义是时代的产物 · 第一节 中频考点","items":["产生时间：19世纪40年代中期","客观条件：资本主义的发展及其内在矛盾的尖锐化","阶级基础：工人阶级作为独立的政治力量登上世界舞台","时代需要：马克思主义的产生是历史时代提出的一项伟大任务","三大工人运动：法国里昂工人起义、英国人民宪章运动、德国西里西亚工人起义","法国里昂工人起义揭开工人运动史上第一页"]},{"s":"马克思主义对人类文明成果的继承与创新 · 第一节 高频考点","items":["马克思主义组成部分及其直接理论来源","马克思主义哲学 ← 德国古典哲学（费尔巴哈和黑格尔）","马克思主义政治经济学 ← 英国古典政治经济学（亚当·斯密和大卫·李嘉图）","科学社会主义 ← 英法两国空想社会主义（圣西门、傅立叶和欧文）","马克思主义产生的自然科学基础：细胞学说、生物进化论和能量守恒与转化定律"]},{"s":"马克思主义在实践中不断发展 · 第一节 低频考点","items":["马克思主义公开问世的标志性著作是《哲学的贫困》和《共产党宣言》","1848年2月，《共产党宣言》发表","马克思主义中国化的理论成果：毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想（最新理论成果）"]},{"s":"马克思主义的科学内涵 · 第二节 中频考点","items":["马克思主义是由马克思、恩格斯创立的，为他们的后继者所发展的，关于无产阶级和人类解放的科学","马克思主义哲学是科学的世界观和方法论，政治经济学揭示了资本主义的发展规律，科学社会主义理论处于核心地位"]},{"s":"马克思主义的理论特征 · 第二节 中频考点","items":["根本理论特征：以实践为基础的科学性和革命性的统一"]},{"s":"马克思主义的理论品质 · 第二节 低频考点","items":["理论品质：与时俱进"]},{"s":"马克思主义的社会理想 · 第二节 中频考点","items":["马克思主义的社会理想是推翻资本主义、实现社会主义和共产主义","我国各族人民的共同理想是把我国建设成为富强民主文明和谐美丽的社会主义现代化国家"]},{"s":"马克思主义是行动的指南 · 第三节 低频考点","items":["必须从客观存在的实际情况出发，而不能从马克思主义的一般原理出发","要用马克思主义的立场、观点、方法研究和解决我国改革开放和现代化建设中的实际问题"]},{"s":"学习马克思主义的根本方法 · 第三节 中频考点","items":["根本方法是理论联系实际，这是由马克思主义的实践性决定的，也是由学习马克思主义的目的决定的","学习马克思主义的目的全在于应用，在实际工作中反对经验主义和教条主义两种倾向"]}]}],"2":[{"root":"第一章　世界是统一的物质世界","sects":[{"s":"世界是统一的物质世界 · 第一节 高频考点","items":["哲学的基本问题包含两个方面","思维与存在谁是第一性问题：唯物主义认为物质第一性、意识第二性；唯心主义认为意识第一性、物质第二性","思维与存在是否具有同一性问题：可知论认为世界是可以认识的；不可知论认为世界是不可能认识或不可能彻底认识的","哲学的两大基本派别","唯物主义：古代朴素唯物主义认为水、火、气等是世界的本原","唯物主义：近代形而上学（机械）唯物主义认为原子是世界的本原","唯物主义：辩证唯物主义和历史唯物主义（马克思）","唯心主义：主观唯心主义认为主观精神是世界的本原，如感觉、经验、思想等（人）","唯心主义：客观唯心主义认为客观精神是世界的本原，如理念、绝对精神、上帝等（外力）"]},{"s":"物质是不依赖于意识又能为意识所反映的客观实在 · 第一节 中频考点","items":["物质的唯一特性是客观实在性","列宁对物质的定义"]},{"s":"运动是物质的根本属性 · 第一节 中频考点","items":["运动是物质的存在方式和根本属性","否认物质是运动的承担者或主体，必然导致唯心主义","世界上的事物都是绝对运动和相对静止的统一，是动中有静，静中有动","这是唯物辩证法的观点，是正确的","只承认静止，否认运动，会导致形而上学；只承认运动，否认静止，会导致相对主义诡辩论"]},{"s":"时间和空间是物质运动的存在方式 · 第一节 低频考点","items":["时间：含义——物质运动的持续性、顺序性；特点——一维性（朝着一个方向向前发展，具有不可逆性）","空间：含义——物质运动的广延性、伸张性；特点——三维性（长、宽、高确定空间）","时间和空间既是绝对的、无限的，又是相对的、有限的，是绝对和相对、无限和有限的统一","这是辩证唯物主义的观点，是正确的"]},{"s":"实践的本质、特点、形式和作用 · 第一节 中频考点","items":["实践含义：主体能动地改造和探索客体的客观物质活动","主体：人（个人主体、群体主体、类主体）","客体/对象：自然客体、社会客体、精神客体","基本特点：客观性、自觉能动性、社会历史性","基本形式：物质生产实践（最基本）、处理社会关系的实践、科学实验","人生活于其中的世界是与人的实践相联系的物质世界","第一，人的实践活动与自然界的二重化；第二，社会历史是人们的实践活动创造的；第三，实践是人的存在方式"]},{"s":"社会生活在本质上是实践的 · 第一节 低频考点","items":["实践是人类社会产生、存在和发展的基础，是社会生活的本质"]},{"s":"世界联系的普遍性和多样性 · 第二节 中频考点","items":["唯物辩证法认为，物质世界是普遍联系和永恒发展的。联系和发展的观点是唯物辩证法的总特征","联系的特点：客观性——要求我们从事物本身固有的联系中把握事物","联系的特点：普遍性——要求我们用联系的观点看问题","联系的特点：多样性——要求我们坚持全面的观点，抓住事物的本质联系"]},{"s":"世界的运动发展 · 第二节 低频考点","items":["发展的实质是新事物的产生和旧事物的灭亡","区分新旧事物的根本标志——是否符合事物发展的必然趋势，是否具有强大的生命力和远大的发展前途","新事物必然战胜旧事物的原因——新事物符合事物发展的必然趋势，优越于旧事物，符合广大人民群众的利益和要求"]},{"s":"两种对立的发展观 · 第二节 低频考点","items":["唯物辩证法——联系、发展、承认事物内部矛盾","形而上学——孤立、静止、否认事物内部矛盾","二者的根本对立和斗争焦点在于是否承认矛盾是事物发展的动力"]},{"s":"对立统一规律 · 第二节 中频考点","items":["对立统一规律是唯物辩证法的实质与核心，是宇宙的根本规律","对立统一规律也叫做矛盾规律","矛盾分析法是最根本的认识方法","对立统一规律揭示了事物发展的动力和源泉"]},{"s":"矛盾的同一性和斗争性 · 第二节 低频考点","items":["矛盾的两种基本属性是同一性和斗争性"]},{"s":"矛盾是事物发展的动力 · 第二节 低频考点","items":["内因是事物变化发展的根据，是第一位的原因；外因是事物发展变化的条件，是第二位的原因。外因通过内因起作用"]},{"s":"矛盾的普遍性和特殊性 · 第二节 中频考点","items":["普遍性：矛盾无处不在，无时不有，时时有矛盾，事事有矛盾","要求我们树立矛盾观点，坚持矛盾分析方法，坚持“两点论”，全面地看问题","矛盾的特殊性要求我们坚持具体问题具体分析","矛盾的普遍性与特殊性是辩证统一的，二者相互联结、相互区别，在一定条件下可以相互转化","矛盾的普遍性与特殊性的辩证关系原理是矛盾问题的精髓"]},{"s":"矛盾发展的不平衡性 · 第二节 中频考点","items":["不同矛盾：主要矛盾——居于支配地位，起决定作用；次要矛盾——处于服从地位","同一矛盾：主要方面——居于支配地位，起着主导作用的方面（主流）；次要方面——处于被支配地位的方面（支流）","主要矛盾和次要矛盾、矛盾的主要方面和次要方面的原理，要求我们在实际工作中坚持两点论和重点论的统一"]},{"s":"质量互变规律 · 第二节 高频考点","items":["量变：事物数量的增减和场所的变更，以及事物构成成分在空间上排列组合的变化","质变：事物根本性质的变化，是事物由一种质态向另一种质态的飞跃","二者的区分：事物的变化是否超出度的范围，是区分量变和质变的根本标志","二者的关系是辩证统一的。量变是质变的必要准备，质变以量变为前提和基础；质变是量变的必然结果；二者相互渗透","质量互变规律揭示了事物发展的状态和形式"]},{"s":"否定之否定规律 · 第二节 中频考点","items":["辩证的否定是事物的自我否定，是联系和发展的环节，是扬弃，即既克服又保留","举例：对传统文化的批判继承","否定之否定规律揭示了事物的发展是前进性与曲折性的统一","否定之否定规律揭示了事物发展的趋势和道路"]},{"s":"世界联系与发展的基本环节 · 第二节 低频考点","items":["原因和结果、必然性和偶然性、可能性和现实性、内容和形式、本质和现象"]},{"s":"规律 · 第三节 低频考点","items":["含义：物质运动发展过程中本质的、必然的、稳定的联系","特点：客观性和普遍性","社会发展是有规律的自然历史过程。与自然规律相比，社会规律是通过人的活动实现的"]},{"s":"意识的起源、本质及其能动作用 · 第三节 高频考点","items":["起源——意识是自然界长期发展的产物，是社会性劳动的产物（决定因素）","意识是人脑的机能，人脑是意识的物质器官","意识是客观世界的主观映象，是人脑对客观世界的反映","意识是社会的产物","注意是“人脑”，不是“大脑”","能动作用——意识活动具有目的性和计划性","意识活动具有主动性和创造性","意识能调节人的生理活动","意识能通过指导实践改造客观物质世界"]},{"s":"发挥主观能动性和尊重客观规律的关系 · 第三节 中频考点","items":["尊重客观规律和发挥主观能动性是辩证统一的：尊重客观规律是正确发挥主观能动性的前提，认识和利用客观规律又必须充分发挥人的主观能动性"]},{"s":"实事求是是马克思主义哲学的精髓 · 第四节 低频考点","items":["实事求是是党的思想路线的核心","实事求是是中国共产党人认识和改造世界的根本要求，是我们党的根本思想方法、工作方法和领导方法，是党带领人民推动中国革命、建设和改革事业不断取得胜利的重要法宝"]},{"s":"解放思想和实事求是的辩证统一 · 第四节 低频考点","items":["实事求是是解放思想的目的，解放思想就是为了更好地做到实事求是","解放思想是坚持实事求是的前提，只有解放思想，才能切实做到实事求是"]}]}],"3":[{"root":"第二章　认识的本质及其规律","sects":[{"s":"实践是认识的基础 · 第一节 高频考点","items":["列宁：实践的观点是认识论的首要的和基本的观点","实践是认识的来源","实践是认识发展的动力","实践是检验真理的唯一标准","实践是认识的目的"]},{"s":"认识是主体对客体的能动的反映 · 第一节 高频考点","items":["认识主体：是指认识和实践活动的承担者，是现实的、具体的人","认识主体具有能动性，这是认识主体的突出特点","认识客体：人的实践活动和认识活动所指向的对象","二者关系：实践关系、认识关系、相互作用","实践关系是首要的基本的关系","认识的真正本质是在实践中主体对客体的能动反映","能动反映论区别于机械反映论的根本标志是认为认识的过程是反映与创造的统一"]},{"s":"从感性认识到理性认识 · 第二节 高频考点","items":["感性认识是认识的初级阶段，它是对事物的各个片面、现象和外部联系的反映，是具体的、丰富的、生动的","感性认识的三种形式：感觉、知觉和表象","理性认识是认识的高级阶段，它是对事物的全体、本质和内部联系的反映，是抽象的、间接的、相对稳定的","理性认识的三种形式：概念、判断和推理","二者的辩证关系——区别：感性认识是对事物表面的、直接的、具体的、个别特性的反映，是不深刻的、片面的认识；理性认识是对事物本质的、全体的、间接的、概括的反映，是深刻的、全面的、相对稳定的认识","二者的辩证关系——联系：理性认识依赖于感性认识，感性认识有待于发展到理性认识，感性认识和理性认识相互渗透","认识的第一次飞跃是从感性认识向理性认识的飞跃","第一次飞跃的实现条件：感性材料必须十分丰富，必须合于实际；必须有正确的思维方法"]},{"s":"从理性认识到实践 · 第二节 低频考点","items":["认识过程的第二次飞跃是从理性认识到实践"]},{"s":"认识过程的多次反复和有限与无限的辩证统一 · 第二节 中频考点","items":["认识的反复性产生的原因——认识客体方面：客观事物本身具有复杂性；事物的矛盾有个展开和发展的过程；科学技术条件的限制","认识的反复性产生的原因——认识主体方面：主体的生理因素、知识水平、生活经验、认识能力及其立场、观点、方法的限制","认识是有限和无限的辩证统一：每个时代的个人每一次具体的认识是有限的；整个人类的无止境的世代更替的认识是无限的","实践——认识——实践的循环往复体现了认识和实践的统一是具体的、历史的"]},{"s":"真理和谬误 · 第三节 低频考点","items":["真理：正确地反映客体的认识","谬误：歪曲地反映客体的认识","二者关系——对立：相互排斥、相互否定；统一：相互依存、相互转化"]},{"s":"真理的属性 · 第三节 高频考点","items":["客观性、绝对性（绝对真理）、相对性（相对真理）","真理的绝对性和相对性的关系：二者相互依存。二者相互包含、相互渗透。相对真理向绝对真理转化","马克思主义是真理，是绝对性和相对性的统一"]},{"s":"实践是检验真理的唯一标准 · 第三节 中频考点","items":["真理标准问题上的两种错误观点：①用伟人、圣人之言作为衡量真理的标准；②实用主义哲学提出的“有用即真理”","实践标准的唯一性：①是不是真理就是要判明认识与认识对象是否相一致、相符合；②实践具有直接现实性的品格"]},{"s":"真理与价值的辩证统一 · 第三节 低频考点","items":["真理与价值的对立统一——对立：真理体现的是认识与认识对象的关系，是认识与对象相一致、相符合","真理与价值的对立统一——统一：真理能够指导社会实践，人们通过在真理指导下的实践，成功地改造世界，以这种实践的成果来满足人的需要，这就是真理所表现出来的价值属性。真理与正确的价值观相一致，正确的价值观是在真理指导下形成的","真理的价值表现在真理的功能上：真理具有指导实践的功能；真理具有再认识的功能；真理具有教育和激励的功能"]},{"s":"培育和践行社会主义核心价值观 · 第三节 低频考点","items":["国家层面：富强、民主、文明、和谐","社会层面：自由、平等、公正、法治","个人层面：爱国、敬业、诚信、友善"]},{"s":"认识世界与改造世界的统一 · 第三节 中频考点","items":["认识的目的全在于运用","马克思主义哲学坚持认识和实践的统一，坚持认识世界和改造世界的统一，认为认识的目的全在于运用","认识世界与改造世界的统一是马克思主义哲学认识论的内在本质和要求","一切从实际出发、实事求是","一切从实际出发，是马克思主义哲学的根本要求","党的思想路线是一切从实际出发，理论联系实际，实事求是，在实践中检验和发展真理","实事求是是党的思想路线的核心；实事求是是马克思主义哲学的精髓和活的灵魂；实事求是是马克思主义认识论的根本原则","党的群众路线是一切为了群众，一切依靠群众，从群众中来，到群众中去"]}]}],"4":[{"root":"第三章　人类社会及其发展规律","sects":[{"s":"社会存在和社会意识 · 第一节 高频考点","items":["社会存在是指社会物质生活条件的总和，包括地理环境、人口因素和物质生活资料的生产方式","地理环境在社会发展中的作用主要是通过对物质生产的影响实现的","生产方式包括生产力和生产关系两个方面","社会意识——按反映社会存在的程度和特点，划分为社会心理和思想体系","社会意识——按对经济基础的关系不同和反映社会存在的方式不同，划分为意识形态和非意识形态","社会意识——按主体范围，划分为个体意识和群体意识","社会存在和社会意识的关系：社会存在决定社会意识，社会意识反作用于社会存在，社会意识具有相对独立性","社会存在和社会意识的关系问题是历史观的基本问题","社会意识的相对独立性：社会意识与社会存在变化发展的非完全同步性","社会意识的相对独立性：社会意识与社会经济发展水平具有不平衡性","社会意识的相对独立性：社会意识的发展具有历史继承性","社会意识的相对独立性：社会意识各种形式之间相互作用、相互影响","社会意识对社会存在的反作用或称能动性，是社会意识相对独立性的重要表现"]},{"s":"生产力和生产力系统 · 第一节 高频考点","items":["生产力是人类从自然界获取物质资料的能力，生产力反映的是人与自然的关系","生产工具是劳动资料的主要内容，是生产力发展水平的主要标志","科学技术是第一生产力（邓小平）"]},{"s":"生产关系和生产关系体系 · 第一节 中频考点","items":["生产关系是指人们在物质生产过程中结成的经济关系（生产关系反映的是人与人之间的经济关系）","生产关系体系——生产资料所有制形式：决定作用、基础","生产关系体系——人们在生产中的地位及其相互关系（包括交换）","生产关系体系——产品的分配方式"]},{"s":"生产力和生产关系之间的矛盾 · 第一节 低频考点","items":["生产力决定生产关系。生产力决定生产关系的性质和改变","生产关系反作用于生产力。适合生产力的生产关系促进生产力的发展；不适合生产力的生产关系阻碍生产力的发展","生产关系必须适合生产力性质是人类社会发展最基本、最普遍的规律","生产关系可以先于也可以落后于生产力而存在，不一定总是适应生产力的发展要求"]},{"s":"经济基础 · 第一节 低频考点","items":["经济基础是指一个社会中占统治地位的生产关系各个方面的总和"]},{"s":"上层建筑 · 第一节 中频考点","items":["政治上层建筑或实体性上层建筑（有形实体）：指政治法律制度及军队、警察、法院、监狱、政府机关等设施以及与之相适应的一套组织","观念上层建筑或思想上层建筑（无形）：包括政治、法律、艺术、道德、宗教、哲学等各种服务于统治阶级的意识形态","二者既相互区别，又互相依赖、互相渗透、互相作用、互相转化。观念上层建筑决定政治上层建筑，政治上层建筑影响观念上层建筑"]},{"s":"经济基础和上层建筑之间的矛盾 · 第一节 中频考点","items":["经济基础决定上层建筑，上层建筑反作用于经济基础，经济基础和上层建筑之间的矛盾运动，这三项内容构成上层建筑必须适合经济基础发展要求的规律","任何上层建筑都根源于经济基础"]},{"s":"社会形态的划分 · 第一节 中频考点","items":["经济社会形态是直接或间接以生产关系的性质为标准划分的社会形态","五种社会形态划分法：原始社会、奴隶社会、封建社会、资本主义社会、共产主义社会（按照生产关系的不同性质划分·马克思）","三种社会形态划分法：人的依赖性社会（自然经济社会）、物的依赖性社会（商品经济社会）、个人全面发展的社会（产品经济社会）（按照作为社会主体的人的发展状况划分·马克思）","技术社会形态划分法：渔猎社会、农业社会、工业社会、信息社会"]},{"s":"社会形态的发展是自然历史过程 · 第一节 低频考点","items":["社会形态的发展是一种自然历史过程，这种观点属于历史唯物主义（历史唯物论），这句话说的是社会发展具有不以人的意志为转移的客观规律性","正确的观点"]},{"s":"社会历史发展的决定性与选择性 · 第一节 低频考点","items":["社会历史发展的决定性是指历史决定论，社会历史发展的选择性是指主体选择的作用","既承认历史发展的决定性，又承认历史发展的选择性，这属于历史唯物主义（历史唯物论）的观点","正确的观点"]},{"s":"社会形态发展的统一性和多样性 · 第一节 中频考点","items":["有些国家和民族由于特殊的社会历史条件，在社会形态转变过程中，可能超越某一个或某几个社会形态","五种社会形态划分法是就世界范围而言的，不是说每一个国家和民族都一定依次经历五种社会形态"]},{"s":"社会基本矛盾在社会发展中的作用 · 第二节 低频考点","items":["社会基本矛盾是生产力和生产关系之间的矛盾、经济基础和上层建筑之间的矛盾","这两对基本矛盾不是互相孤立、互相平行的，而是相互制约、有主次之分的","生产力与生产关系之间的矛盾，对于经济基础与上层建筑之间的矛盾起着主导作用","生产力和生产关系之间的矛盾的解决，又有赖于经济基础和上层建筑之间的矛盾的解决","社会基本矛盾是社会发展的基本动力"]},{"s":"阶级斗争在阶级社会发展中的作用 · 第二节 高频考点","items":["阶级是生产发展到一定阶段的产物","阶级是经济范畴，也是社会范畴，划分阶级的唯一标准是经济标准","不能用政治标准和思想标准划分阶级","阶级斗争是阶级社会发展的直接动力","物质利益的对立是阶级斗争的根源"]},{"s":"革命和改革在社会发展中的作用 · 第二节 高频考点","items":["社会革命和社会改革是社会运动的两种基本形式，都是推动社会发展的动力","社会革命是阶级斗争的最高表现，是社会基本矛盾的必然产物，其最深刻的根源在于生产力和生产关系之间的矛盾，以及经济基础和上层建筑之间的矛盾","暴力革命是社会革命的基本形式","改革不仅存在于社会主义社会中，而且存在于其他社会形态中（改革的普遍性）","革命是解放生产力，改革也是解放生产力（邓小平）"]},{"s":"人的本质和人与社会的关系 · 第三节 高频考点","items":["人的自然属性是指人的肉体存在及其特性","人的社会属性是指在社会实践活动中人与人结成的各种社会关系","自然属性是人存在的基础","人的本质在于人的社会属性（人的本质是由人的社会属性决定的）","人的本质：劳动是人的本质","人的本质：人的本质是一切社会关系的总和（马克思）","人的本质：人的需要即人的本质","人与社会是具体的、历史的统一——人的出现与社会的产生是一致的；人的活动与社会结构及其发展变化是一致的；社会的本质和人的本质是一致的，这种一致的基础是实践；个人的解放与社会的解放是一致的"]},{"s":"历史观上两种根本对立的观点 · 第三节 中频考点","items":["历史唯心主义（英雄史观）认为，社会意识决定社会存在，历史是由少数英雄人物创造的，否认人民群众是推动历史发展的决定力量","历史唯物主义（群众史观）认为，社会存在决定社会意识，物质资料的生产方式是人类社会存在和发展的基础，人民群众是历史的创造者"]},{"s":"人民群众在历史上的作用 · 第三节 中频考点","items":["人民群众是物质财富的创造者，是精神财富的创造者，是实现社会变革的决定力量","人民群众是历史的创造者，因此必须坚持以人为本。全心全意为人民服务是党的根本宗旨","历史是人民群众创造的，但人民群众不能随心所欲地创造历史，人民群众创造历史的活动受历史条件的制约"]},{"s":"无产阶级政党的群众观点和群众路线 · 第三节 低频考点","items":["群众观点是马克思主义政党的根本观点","党的群众观点的内容：人民群众自己解放自己；全心全意为人民服务；向人民群众负责；向人民群众学习","群众路线是无产阶级政党的生命线和根本工作路线","群众路线的内容：一切为了群众，一切依靠群众，从群众中来，到群众中去"]},{"s":"个人在历史发展中的作用 · 第三节 中频考点","items":["杰出人物有力地推动了历史发展和社会进步","只能说推动，不能说决定","衡量马克思主义政党是否真正履行对人民群众所负责任的一个最重要最可靠的尺度是对自己的错误所抱的态度"]}]}],"5":[{"root":"第四章　资本主义的本质及规律","sects":[{"s":"商品和商品经济 · 第一节 中频考点","items":["商品的含义：为市场交换而生产的有用的产品","商品经济的含义：以商品生产和商品交换为内容，直接以交换为目的而进行生产的经济形式（商品经济是商品生产和商品交换的总称）","商品经济产生和存在的两个基本经济条件","社会分工的产生和存在——一般条件和基础","生产资料和劳动产品属于不同的所有者——决定性条件"]},{"s":"商品的二因素 · 第一节 高频考点","items":["使用价值：含义——一种物品能够满足人们某种需要的属性，即物品的有用性","使用价值是商品的自然属性","价值（最本质因素）：含义——凝结在商品中的无差别的一般人类劳动，即人们的脑力和体力的付出","价值是商品的社会属性"]},{"s":"劳动的二重性 · 第一节 中频考点","items":["具体劳动：生产一定使用价值，具有特定性质、目的和形式的劳动，就是具体劳动","具体劳动创造出使用价值，不同的具体劳动创造出不同的使用价值","具体劳动是生产商品劳动的自然属性","抽象劳动：撇开一切具体形式、无差别的一般人类劳动，就是抽象劳动","生产商品的抽象劳动创造了商品的价值","抽象劳动是生产商品劳动的社会属性"]},{"s":"商品的价值量 · 第一节 高频考点","items":["含义：商品价值是人类一般劳动的凝结","商品的价值量由生产商品的社会必要劳动时间决定（决定因素）","社会必要劳动时间由两个条件决定：第一，由生产的客观标准条件，即现有的社会正常生产条件所决定","社会必要劳动时间由两个条件决定：第二，由生产的主观标准条件，即由社会平均的劳动熟练程度和平均的劳动强度所决定","商品的社会价值和个别价值：社会价值是由社会必要劳动时间所决定的商品价值量","商品的社会价值和个别价值：个别价值是由各个商品生产者的个别劳动时间所形成的价值量","商品交换的两种情况：盈利——个别劳动时间少于社会必要劳动时间（个别价值少于社会价值）","商品交换的两种情况：亏本——个别劳动时间大于社会必要劳动时间（个别价值大于社会价值）","商品价值量与社会必要劳动时间和劳动生产率的关系：单位商品的价值量与社会必要劳动时间成正比","商品价值量与社会必要劳动时间和劳动生产率的关系：单位商品的价值量与生产该商品的劳动生产率成反比"]},{"s":"货币的本质和职能 · 第一节 中频考点","items":["货币的产生：货币是商品交换长期发展的产物","货币的本质：固定地充当一般等价物的商品","货币的职能：价值尺度（最基本职能）、流通手段、支付手段、贮藏手段、世界货币"]},{"s":"以私有制为基础的商品经济的基本矛盾 · 第一节 高频考点","items":["社会劳动与私人劳动的矛盾是以私有制为基础的商品经济的基本矛盾"]},{"s":"商品经济的基本规律 · 第一节 高频考点","items":["价值规律的内容：商品的价值由生产商品的社会必要劳动时间决定，商品交换以价值为基础，实行等价交换","价值规律的表现形式：价格围绕价值上下波动","价值规律对社会经济发展的作用：自发地调节生产资料和劳动力在社会生产各部门之间分配的比例，即调节社会资源的配置","价值规律对社会经济发展的作用：自发地促进社会生产力的发展","价值规律对社会经济发展的作用：引起和促进商品生产者的分化"]},{"s":"货币转化为资本和劳动力成为商品 · 第二节 高频考点","items":["货币转化为资本——劳动力成为商品，是货币转化为资本的前提","劳动力成为商品的两个基本条件：劳动者有人身自由","劳动力成为商品的两个基本条件：劳动者除了自己的劳动力外一无所有","劳动力商品的价值也和其他商品的价值一样，是由生产和再生产劳动力商品的社会必要劳动时间决定的","劳动力商品的价值包括三部分生活资料的价值：维持劳动者自身生存所需的生活资料的价值；劳动者繁育后代所必需的生活资料的价值；劳动者接受教育和训练所支出的费用","劳动力的价值决定还有一个重要的特点，就是它包括历史和道德的因素","劳动力的使用价值是进行生产劳动的能力","劳动力商品的使用价值的特殊性在于它不仅能创造出价值，而且能创造出比劳动力自身价值更大的价值，从而为劳动力的购买者带来剩余价值"]},{"s":"资本主义的生产过程 · 第三节 中频考点","items":["资本主义的生产过程是劳动过程和价值增殖过程的统一","劳动过程：工人在资本家的监督下劳动，劳动产品归资本家所有","价值增殖过程：工人创造剩余价值","剩余价值就是由雇佣工人创造的、被资本家无偿占有的超过劳动力价值的价值"]},{"s":"资本的本质及不变资本和可变资本 · 第二节 高频考点","items":["资本的本质不是物，而是资产阶级和无产阶级之间剥削与被剥削的生产关系","不变资本：以生产资料形式存在的资本，在生产过程中不发生价值量的变化","可变资本：以劳动力形式存在的资本，在生产过程中发生了量的变化，实现了价值增殖","通过区分不变资本和可变资本，说明剩余价值不是由全部资本产生的，也不是由不变资本产生的，而是由可变资本产生的，工人的剩余劳动是剩余价值的唯一源泉"]},{"s":"剩余价值率 · 第三节 高频考点","items":["剩余价值率是剩余价值与可变资本的比率，即m′=m/v，它表明了资本家对工人的剥削程度","绝对剩余价值——在必要劳动时间不变的条件下，由于工作日的绝对延长而生产的剩余价值","相对剩余价值——在工作日长度不变的条件下，由于缩短必要劳动时间、相应延长剩余劳动时间而生产的剩余价值","剩余价值规律是资本主义的基本经济规律"]},{"s":"资本积累 · 第二节 高频考点","items":["含义：把剩余价值再转化为资本，或者说剩余价值的资本化","源泉：剩余价值是资本积累的源泉","实质：资本家无偿占有工人创造的剩余价值，进行资本积累来增大规模，以便继续占有更多的剩余价值，从而占有不断增大的资本来扩大对工人的剥削和统治","后果：资本有机构成提高、相对过剩人口（失业人口）的形成、严重的贫富两极分化","历史作用：社会劳动生产力的提高和劳动的社会化","历史趋势：用和生产社会化性质相适应的生产资料社会主义公有制代替资本主义私有制"]},{"s":"单个资本的循环和周转 · 第三节 高频考点","items":["单个资本的循环——购买阶段：为生产剩余价值准备条件；货币资本转化为生产资本","单个资本的循环——生产阶段：是生产剩余价值的阶段；是资本循环中决定性的阶段；生产资本转化为商品资本；资本实现了价值增殖","单个资本的循环——销售阶段：商品资本转化为增殖了的货币资本","资本周转的含义：不断重复、周而复始的资本循环过程，就是资本周转","影响资本周转速度快慢的两个因素：资本周转时间的长短","影响资本周转速度快慢的两个因素：生产资本的构成","资本家加速资本周转的目的是增加年剩余价值量，提高年剩余价值率"]},{"s":"社会总资本的再生产 · 第三节 中频考点","items":["社会资本再生产的核心问题是社会总产品的实现问题","社会总产品——从实物形态上按其最终用途分为生产资料和消费资料","社会总产品——从价值形态上区分为不变价值资本、可变价值资本、剩余价值","社会总产品的实现：价值补偿；物质补偿"]},{"s":"剩余价值的分配 · 第三节 高频考点","items":["利润是剩余价值的转化形式","剩余价值转化为利润后，剩余价值被作为全部预付资本的产物，掩盖了剩余价值与工人的剩余劳动的相互联系，因而也就掩盖了剩余价值的真实来源","利润率是剩余价值与可变资本的比率，利润率是剩余价值率的转化形式","利润转化为平均利润：等量资本获得等量利润，即形成平均利润","不同生产部门之间平均利润的形成，是部门之间竞争的结果。形成平均利润时，资本的转移才会趋于停止","平均利润率是全社会的剩余价值总量与社会总资本的比率","平均利润本质上是全社会的剩余价值在各生产部门资本家之间的重新分配，体现着整个资产阶级剥削整个工人阶级的经济关系","平均利润率规律是资本主义的客观经济规律","利润率趋向下降规律是资本主义的客观经济规律","商业资本家预付一定数量的货币资本从事商业活动的目的，是取得商业利润","商业资本家获得商业利润的具体途径是商品的销售价格高于商品的购买价格，其间的差额就包含着商业利润","商业利润的来源是产业部门的工人创造的剩余价值","商业利润的多少，同样受平均利润率规律的支配，这取决于产业资本家和商业资本家之间的竞争","借贷资本的本质是为了取得利息而暂时贷给职能资本家使用的货币资本","利息就是职能资本家使用借贷资本而让给借贷资本家的一部分剩余价值，它是剩余价值的特殊转化形式","在资本主义社会，货币资本的借贷主要是通过银行进行的","资本主义银行是专门经营货币资本的企业","银行所掌握的自有资本和借入资本的总和即银行资本","自有资本：银行资本家自己投入的资本，占银行资本的一小部分","借入资本：银行吸收的存款，占银行资本的大部分","银行向外贷款所收取的贷款利息，大于吸收存款所支付的存款利息，两者的差额再减去经营银行的业务费用，就形成银行利润","银行利润在数量上相当于银行资本家自有资本所获得的平均利润"]},{"s":"资本主义经济危机 · 第三节 中频考点","items":["根本特点/最根本的现象/典型特征是商品生产过剩","实质是生产相对过剩的危机","根源于资本主义生产方式的基本矛盾，即生产的社会化与生产资料私人资本主义占有形式之间的矛盾","经济危机是周期性爆发的，其原因在于资本主义基本矛盾运动的阶段性","资本主义再生产周期的阶段是危机、萧条、复苏、高涨。其中，危机是决定性阶段"]},{"s":"资本主义的政治制度及其本质 · 第四节 高频考点","items":["资本主义国家制度（资本主义政治制度的核心）：国体——都是相同的，都是实行资产阶级专政","资本主义国家制度（资本主义政治制度的核心）：政体——不尽相同，主要有君主立宪制和民主共和制","资本主义政党制度：一党制","资本主义政党制度：两党制（如美国）","资本主义政党制度：多党制（如法国、意大利）","资本主义普选制度：其平等权利具有虚伪性，从本质上看，它是资产阶级进行统治的工具，是实行资产阶级专政的一种手段","资本主义“三权分立”制度：立法权，由议会掌握；行政权，由政府掌握；司法权，由法院掌握","资本主义民主制度：核心和主要标志是议会制","资本主义民主制度：本质是维护资产阶级的阶级利益，为资产阶级专政服务"]},{"s":"资本主义的意识形态及其本质 · 第四节 低频考点","items":["历史进步性：资本主义意识形态在反对封建专制的斗争中，以及在资本主义生产方式产生与发展的上升时期，反映了社会进步的要求","阶级局限性：本质上是维护资本主义剥削制度的思想体系","具有鲜明的阶级性","核心：利己主义"]}]}],"6":[{"root":"第五章　资本主义的发展及其趋势","sects":[{"s":"资本主义的发展阶段 · 第一节 中频考点","items":["自由竞争资本主义（19世纪末20世纪初之前）","垄断资本主义（19世纪末20世纪初）——私人垄断（也称为一般垄断）；国家垄断（出现于二战后）","两大阶段","二战后，国家垄断取代私人垄断成为西方发达国家当代资本主义发展的新形式、新特征","垄断资本主义的基本经济特征：垄断在经济生活中占统治地位","垄断资本主义的基本经济特征：金融资本和金融寡头的统治","垄断资本主义的基本经济特征：资本输出在经济生活中占重要地位","垄断资本主义的基本经济特征：国际垄断同盟在经济上瓜分世界","垄断资本主义的基本经济特征：垄断资本主义列强瓜分和重新瓜分世界"]},{"s":"垄断的形成 · 第一节 低频考点","items":["社会化生产力的发展是垄断产生的物质条件和基础","垄断是从自由竞争中产生的"]},{"s":"垄断组织的形成与发展 · 第一节 中频考点","items":["20世纪前半期的垄断组织形式有卡特尔、辛迪加、托拉斯、康采恩","20世纪后半期垄断组织的形式是混合联合企业","当代国际垄断组织的主要形式是跨国公司"]},{"s":"金融资本和金融寡头的形成及其统治 · 第一节 高频考点","items":["金融资本：垄断的工业资本和银行资本，通过金融联系、资本参与和人事参与，融合或混合生长构成的一种新的资本形式，是垄断资本主义国家中社会经济生活各个方面实际上的统治者","金融寡头：掌握了金融资本，操纵国民经济命脉，并在实际上控制国家政权的少数垄断资本家或垄断资本家集团","金融寡头的统治方式：在经济上的统治主要是通过实行“参与制”实现的","金融寡头的统治方式：在政治上的统治主要是通过“个人联合”实现的"]},{"s":"垄断和竞争 · 第一节 中频考点","items":["垄断阶段竞争依然存在的原因：竞争是商品经济存在和发展的基本条件和核心机制，有商品经济就必然存在竞争","垄断阶段竞争依然存在的原因：资本主义经济是发达的商品经济和市场经济，竞争当然不会消失","虽然在某些部门存在着垄断组织，但也存在未形成垄断的部门及大量的非垄断企业，他们之间是竞争的关系；垄断企业之间本质上也依然是相互竞争的关系"]},{"s":"垄断利润及其来源 · 第一节 中频考点","items":["定义：垄断资本凭借其在生产和流通中的垄断地位所获得的大大超过平均利润的高额利润","实现：主要是通过垄断组织制定的垄断价格来实现的","垄断高价是指垄断资本在出售产品时规定的超过商品价值和生产价格的垄断价格","垄断低价是指垄断资本在购买生产资料时规定的低于其价值和生产价格的垄断价格","来源：归根到底来自工人阶级和劳动人民创造的剩余价值"]},{"s":"国家垄断资本主义的产生和发展 · 第一节 高频考点","items":["垄断资本同国家政权相结合，形成国家垄断资本主义","二战后，国家垄断资本主义在主要发达资本主义国家有很大发展","国家垄断资本主义的产生，归根到底是社会生产力发展的要求和结果","二战后国家垄断资本主义大发展的原因：第一，仅靠私人垄断资本的力量，无法满足大规模经济建设所需要的巨额资金","二战后国家垄断资本主义大发展的原因：第二，在一些大规模公共设施的建设上，私人垄断资本无能为力或不愿进行投资建设","二战后国家垄断资本主义大发展的原因：第三，一些大型、基础性、前导性的科学研究项目，私人垄断资本不愿涉足","二战后国家垄断资本主义大发展的原因：第四，日益严重的生产过剩问题仅靠私人垄断资本难以解决","二战后国家垄断资本主义大发展的原因：第五，社会化大生产的发展要求国家进行宏观经济调控","二战后国家垄断资本主义大发展的原因：第六，在经济利益关系的调整方面，国家的再分配功能也越来越重要","国家垄断资本主义的基本形式：国家直接掌握的垄断资本，即国有经济、国有企业","国家垄断资本主义的基本形式：国家和私人资本在企业内部、外部的结合","资本主义国家宏观经济管理与调节的任务和目标：总任务——促进市场总供给和总需求的平衡","资本主义国家宏观经济管理与调节的任务和目标：主要目标——保持经济的稳定和一定程度的增长，保持币值和物价的稳定，实现充分就业，保持国际国内收支的大体平衡等","资本主义国家对经济的调控方式与手段：调控方式——直接调节、控制和介入；间接调节和控制，主要是运用经济手段（主要的调控方式）","资本主义国家对经济的调控方式与手段：调控手段——主要是经济手段和法律手段","国家垄断资本主义宏观经济调控的主要政策：财政政策（包括财政收入和财政支出）","国家垄断资本主义宏观经济调控的主要政策：货币政策——调节利率（主要通过利率高低和差别利率）","国家垄断资本主义宏观经济调控的主要政策：货币政策——调节货币流通量（三大手段，即公开市场业务、最低准备金率政策、再贴现利率政策）","国家垄断资本主义宏观经济调控的主要政策：计划管理","国家垄断资本主义的实质：私人垄断资本利用国家机器来为其利益服务"]},{"s":"垄断资本在世界范围的扩展 · 第一节 中频考点","items":["资本输出——借贷资本输出和生产资本输出","国际垄断组织的产生和发展——建立国际垄断同盟"]},{"s":"经济全球化的原因 · 第二节 低频考点","items":["新科学技术的发展（特别是计算机、通信技术）","国际贸易的自由程度大大提高","国际资本流动的大幅增加"]},{"s":"经济全球化的主要内容 · 第二节 中频考点","items":["生产全球化","贸易全球化","资本全球化","经济全球化的本质：资源配置的国际化"]},{"s":"2008年国际金融危机以来资本主义的矛盾与冲突 · 第二节 低频考点","items":["经济发展失调","政治体制失灵","社会融合机制失效","这些问题根源于资本主义制度本身和资本主义的基本矛盾"]},{"s":"经济全球化的影响 · 第二节 低频考点","items":["促进社会分工和生产要素的流动和优化配置，由此带来巨大分工收益，推动世界生产力发展","积极：发达国家是经济全球化的实际领导者和主要受益者","积极：对发展中国家也有一定的积极影响","消极：发达国家与发展中国家的差距在扩大","消极：在经济增长中忽视社会进步，环境恶化与经济全球化有可能同时发生","消极：国家内部和国际社会都出现不同程度的治理危机","消极：爆发全球性经济危机的风险不断增大"]},{"s":"当代资本主义新变化的主要表现 · 第二节 高频考点","items":["生产力方面——产业结构：转向信息化、服务化和高科技化的趋势","生产力方面——产业结构：第三产业迅速崛起，第一、第二产业比重大幅下降","生产力方面——生产力要素：劳动者——脑力劳动者；劳动工具——“四机系统”、智能化；劳动对象——人工合成材料、新资源、信息资源","生产力方面——生产管理","生产关系方面——所有制关系：资本社会化；私人企业股权分散化，法人资本所有制崛起","生产关系方面——劳资关系：建立劳资共决、职工参与决策、终身雇佣、职工持股等制度","生产关系方面——分配关系：实行社会福利政策，通过再分配手段缓和社会矛盾","上层建筑方面：政治制度与法制的有效结合；国家管理经济和社会的职能增强；资产阶级的民主形式进一步扩大，公民权利的内涵与外延有新的扩展；意识形态中左翼与右翼的分歧逐渐减弱，多元化的价值取向更加鲜明","上层建筑方面：对国家权力机构的监督和制约的内外因素大大加强；国家权力的重心由议会向政府转移"]},{"s":"当代资本主义新变化的原因 · 第二节 低频考点","items":["生产力方面：生产力自身发展规律，特别是科学技术自身发展规律的作用","生产关系方面：在所有制关系上，资本主义国家在其自身范围内不断调整，以适应生产力发展的要求","上层建筑方面：当代资本主义国家中上层建筑的新变化是经济基础发展变化所要求的"]},{"s":"当代资本主义新变化的实质 · 第二节 低频考点","items":["当代资本主义虽然发生了许多新变化，但经济基础仍然是资本主义的私人占有制","资本主义生产社会化与生产资料私人占有的基本矛盾依然存在，导致经济危机的根源依然存在","目前西方发达资本主义国家的新变化，说明它在总的量变过程中，已经发生了某些阶段性的部分质变"]},{"s":"资本主义的历史地位 · 第三节 低频考点","items":["资本主义社会经济形态代替封建社会经济形态，是人类历史的一大进步；然而它迟早要被更先进的社会主义经济形态代替","资本主义经济制度建立的初期推动了生产力的巨大发展；但后期又日益暴露出不适应生产力发展的一面","国家垄断资本主义是社会主义的最充分的物质准备，是社会主义的前阶（列宁）"]},{"s":"资本主义基本矛盾的发展及向社会主义过渡的必然性 · 第三节 低频考点","items":["资本主义生产方式决定了它的历史过渡性质","资本主义在其发展过程中，造就了社会化的生产力和置自身于死地的社会力量（无产阶级）","社会主义必然取代资本主义，是生产关系一定要适合生产力状况这一经济规律的客观要求"]},{"s":"资本主义为社会主义代替的历史必然性和长期性 · 第三节 低频考点","items":["资本主义向社会主义过渡的总趋势是必然的历史走向","资本主义向社会主义过渡的过程是复杂的、曲折的和长期的历史过程"]}]}],"7":[{"root":"第六章　社会主义的发展及其规律","sects":[{"s":"社会主义从空想到科学的发展 · 第一节 高频考点","items":["19世纪初期欧洲的三大空想社会主义者：法国的圣西门、傅立叶和英国的欧文","早期空想社会主义的代表作：英国人莫尔的《乌托邦》、意大利人康帕内拉的《太阳城》","马克思和恩格斯1848年2月发表《共产党宣言》，这是社会主义思想史上的第一个纲领性文件，它标志着科学社会主义理论公开面世","世界上第一个无产阶级政党是“共产主义者同盟”"]},{"s":"无产阶级革命与社会主义制度的建立 · 第一节 高频考点","items":["无产阶级革命是迄今人类历史上最广泛、最彻底、最深刻的革命，是不同于以往一切革命的最新类型的革命","列宁提出社会主义革命可以在一国或数国首先胜利的理论","世界上第一个社会主义国家：苏维埃俄国"]},{"s":"列宁领导下的苏维埃俄国对社会主义的探索 · 第一节 低频考点","items":["1917年-1924年，在列宁领导下苏维埃俄国对社会主义道路的探索大体可分三个阶段，即：进一步巩固苏维埃政权时期、战时共产主义时期（1918-1921）、新经济政策时期（1921-1924）"]},{"s":"斯大林领导下的苏联对社会主义的探索 · 第一节 低频考点","items":["1936年12月，在苏维埃第八次非常代表大会上通过的苏维埃宪法宣布：苏联已建成社会主义社会","苏联在斯大林的领导下形成了建设社会主义的苏联模式"]},{"s":"社会主义从一国到多国的发展 · 低频考点","items":["第二次世界大战以后社会主义事业从一国向多国发展壮大"]},{"s":"社会主义在中国焕发出强大生机活力 · 第一节 低频考点","items":["“五位一体”：经济建设、政治建设、文化建设、社会建设、生态文明建设","“四个全面”：全面建成小康社会、全面深化改革、全面依法治国、全面从严治党","2018年3月的全国人民代表大会上，习近平新时代中国特色社会主义思想作为党的指导思想被首次载入宪法（马克思主义中国化的最新成果）"]},{"s":"科学社会主义一般原则 · 第二节 低频考点","items":["如何正确把握：必须始终坚持科学社会主义一般原则，反对任何背离这些原则的错误倾向","如何正确把握：要善于把科学社会主义一般原则与本国实际相结合，创造性地回答和解决革命、建设、改革中的重大问题","如何正确把握：要紧跟时代和实践的发展，在不断总结新鲜经验中进一步丰富和发展科学社会主义一般原则"]},{"s":"经济文化相对落后的国家建设社会主义的艰巨性和长期性 · 第三节 低频考点","items":["在这些国家里大力发展生产力，赶上和超过发达国家是一个长期而艰巨的历史任务","在这些国家里建设社会主义精神文明、发展社会主义民主与完善社会主义法制，充分显示社会主义制度的优越性，也将是一个长期而艰巨的历史任务","这些国家的国家建设和发展是在与资本主义国家并存的环境下，在资本主义发达国家主导的世界政治经济秩序中曲折前进的，面临着国际环境的严峻挑战","这些国家的执政党和广大人民对其发展道路的探索，对社会主义建设客观规律的认识和利用，是一个长期艰苦的过程","社会主义首先在经济文化相对落后的国家取得胜利的原因包括两方面：具备一定程度的社会化生产力；发生社会主义革命时的客观形势和主观条件"]},{"s":"社会主义发展道路的多样性 · 第三节 中频考点","items":["第一，各国在社会主义革命时，其生产力状况和社会发展阶段是不同的","第二，各国的历史传统、文化习俗及具体国情各不相同","第三，在社会主义的实践中，各国都在探索适合本国国情的发展道路，时代在前进，实践在发展，社会主义的发展道路因此而更具多样性"]},{"s":"社会主义在实践探索中开拓前进 · 第三节 中频考点","items":["同一切新生事物一样，社会主义作为一种崭新的社会经济政治制度，其成长过程必然不会一帆风顺","认识社会主义基本矛盾和主要矛盾，认识社会主义建设规律，认识共产党执政的规律，不可能一蹴而就","世界经济政治形势错综复杂的发展变化，国际经济政治秩序和格局的变动演化"]},{"s":"马克思主义政党是新型的革命政党 · 第四节 高频考点","items":["组织原则：马克思主义政党是按照民主集中制原则组织起来的团结统一的党","马克思主义政党的最高纲领和最终奋斗目标，是实现共产主义","马克思主义政党是科学社会主义与工人运动相结合的产物。马克思主义政党产生的条件，一是工人运动的发展，二是科学社会主义理论的传播","马克思主义政党是为人民服务的新型政党，根本宗旨是为人民群众谋利益"]},{"s":"马克思主义政党是领导核心 · 第四节 低频考点","items":["马克思主义政党是社会主义革命、建设和改革的领导核心，主要体现在思想领导、政治领导、组织领导"]}]}],"8":[{"root":"第七章　共产主义崇高理想及其最终实现","sects":[{"s":"社会生产力高度发展和物质财富极大丰富 · 第一节 中频考点","items":["社会生产力的高度发展，是实现共产主义社会的根本条件和基础","共产主义社会是人类社会发展的最高社会形态，它的物质基础是远远高于以往一切社会的高度发达的社会生产力"]},{"s":"实行社会公有制和按需分配 · 第一节 中频考点","items":["马克思主义认为，共产主义社会的分配原则是按需分配，社会主义社会的分配原则是按劳分配","“各尽所能，按需分配”是集中体现着共产主义社会主要特征和本质要求的原则标志，是共产主义社会的显著特征和一面旗帜"]},{"s":"经济的计划调节管理和商品经济的消失 · 第一节 低频考点","items":["在共产主义社会，经济实行计划调节管理、商品经济消失","在共产主义社会，由于实现生产资料的单一社会公有制，既不存在公有制的多种形式，更不存在非公有制经济形式"]},{"s":"阶级的消灭和国家自行消亡 · 第一节 低频考点","items":["在共产主义社会，阶级消灭、国家自行消亡"]},{"s":"精神境界极大提高 · 第一节 低频考点","items":["以集体主义为核心的共产主义人生观、价值观和道德观"]},{"s":"人的自由而全面发展 · 第一节 高频考点","items":["必要条件：人们完全摆脱了生产资料私有制和阶级压迫的束缚；摆脱旧式分工的束缚；摆脱了劳动仅是谋生手段的束缚；摆脱接受教育和训练的限制","劳动的旧式分工在人类历史上突出表现为由工农商分工、城乡分工、脑力劳动和体力劳动分工所形成的“三大差别”，即工农差别、城乡差别、脑力劳动与体力劳动差别","在共产主义社会，旧式分工和三大差别已消失，劳动成为生活的第一需要，人们将获得自由而全面的发展"]},{"s":"全人类的彻底解放 · 第一节 低频考点","items":["人类从自然界奴役下解放出来，摆脱盲目自然力的支配，成为自然界的主人","人类从旧的社会关系束缚下解放出来，摆脱一切剥削压迫和旧式分工的束缚，成为社会关系的主人","人类从剥削阶级的思想观念下解放出来，摆脱传统观念和传统思维方式的束缚，成为社会意识的主人"]},{"s":"实现共产主义是历史发展规律的必然要求 · 第二节 中频考点","items":["基本特征——基础：生产资料公有制","基本特征——目的：满足劳动人民日益增长的物质文化生活需要","基本特征——产品分配：按照有利于社会发展和实现劳动人民利益的原则","基本特征——指导思想：马克思主义，意识形态的核心：集体主义","基本特征——两个阶段：社会主义社会和共产主义社会都属于共产主义社会形态","社会主义基本矛盾的运动，必将推动着社会主义社会过渡到共产主义社会，这是人类历史发展的必然趋势"]},{"s":"实现共产主义是人类最伟大的事业 · 第二节 低频考点","items":["原因：共产主义事业是最高理想与科学理想的统一","原因：马克思和恩格斯科学地预见了共产主义社会这一理想社会制度的基本特征","原因：体现了人类对理想社会目标的追求与符合规律的科学社会实践的有机结合"]},{"s":"实现共产主义是一个不断实践的长期过程 · 第二节 低频考点","items":["原因：实现共产主义要在实践中长期探索","原因：社会主义的充分发展和向共产主义的过渡要经历长期的、艰巨的实践过程","原因：经济落后国家实现共产主义须经历更长的实践过程","原因：共产主义在世界范围内的实现是长期、曲折、复杂的历史过程"]},{"s":"社会主义是走向共产主义的必由之路 · 第三节 中频考点","items":["基本条件：社会生产力的高度发展，为实现共产主义创造物质技术基础","基本条件：全体社会成员的文化教育的普及和科学技术水平的极大提高","基本条件：全体社会成员的思想觉悟和道德品质的极大提高","基本条件：建立起同高度社会化生产相适应的生产资料社会公有制","基本条件：消灭旧的社会分工特别是三大差别，造就出体力和智力全面发展的新人","基本条件：在全世界消灭一切剥削制度和剥削阶级，作为阶级统治工具的国家自行消亡"]},{"s":"坚定共产主义远大理想信念，积极投身中国特色社会主义事业 · 第三节 高频考点","items":["关系：共产主义远大理想和中国特色社会主义共同理想，二者相辅相成、相互促进，有机联系和统一"]}]}]});
